<?php
session_start();require_once __DIR__.'/db_connect.php';require_once __DIR__.'/includes/require_role.php';require_login();require_role(['Management'],'Review Queue');require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/report_snapshots.php';require_once __DIR__.'/includes/budget_revisions.php';require_once __DIR__.'/includes/report_bundles.php';
header('Cache-Control: private, no-store');$filter=($_GET['filter']??'pending')==='all'?'all':'pending';$items=[];$errors=[];$uid=(int)$_SESSION['UserID'];
try{$items=accounting_read($pdo,function()use($pdo,$uid,$filter){
    reporting_actor($pdo,$uid,['Management']);$rows=[];
    foreach(budget_review_queue($pdo,$uid,$filter) as $b){$rows[]=['type'=>'Monthly Budget','period'=>substr($b['budget_month'],0,7),'date'=>$b['prepared_at'],'state'=>$b['state'],'url'=>'budgets.php?revision_id='.(int)$b['id'],'id'=>(int)$b['id'],'who'=>null];}
    // Read-only submission-name projection. Verify captured payload identity before showing it.
    $ids=array_column($rows,'id');if($ids){$s=$pdo->prepare('SELECT id,payload,payload_hash FROM budget_revisions WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$s->execute($ids);$names=[];foreach($s as $b){$payload=json_decode($b['payload'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals($b['payload_hash'],hash('sha256',reporting_json($payload))))throw new ReportingProblem('Submitted budget details need an integrity review.',503);$names[(int)$b['id']]=$payload['prepared_name']??null;}foreach($rows as &$r)$r['who']=$names[$r['id']]??null;unset($r);}
    foreach(report_bundle_queue($pdo,$uid,$filter) as $b)$rows[]=['type'=>'Financial Reports','period'=>substr($b['report_month'],0,7),'date'=>$b['prepared_at'],'state'=>$b['state'],'who'=>$b['prepared_name'],'url'=>'report_bundles.php?bundle_id='.(int)$b['id'].'&component=income_statement'];
    if(report_snapshot_available($pdo)){$sql="SELECT s.id,s.report_month,s.report_year,s.review_status,s.captured_at,u.FullName FROM trial_balance_snapshots s JOIN user_identities u ON u.UserID=s.submitted_by_user_id".($filter==='pending'?" WHERE s.review_status='Requested'":'').' ORDER BY s.id DESC LIMIT 100';foreach($pdo->query($sql) as $b)$rows[]=['type'=>'Trial Balance Copy','period'=>sprintf('%04d-%02d',$b['report_year'],$b['report_month']),'date'=>$b['captured_at'],'state'=>$b['review_status'],'who'=>$b['FullName'],'url'=>'reports.php?snapshot_id='.(int)$b['id']];}
    usort($rows,fn($a,$b)=>strcmp($b['date'],$a['date']));return $rows;
});}catch(Throwable $e){http_response_code(503);$errors[]='Review information is unavailable. Please try again. No decisions have been made.';error_log('Review queue unavailable.');}
layout_begin('Review Queue','management_reviews');ui_page_heading('Review Queue','Open a submitted item to review its exact saved figures.');
?><nav class="ui-actions" aria-label="Queue view"><a class="<?= $filter==='pending'?'ui-primary':'ui-button' ?>" href="management_reviews.php?filter=pending">Needs Review</a><a class="<?= $filter==='all'?'ui-primary':'ui-button' ?>" href="management_reviews.php?filter=all">Submission History</a></nav>
<?php foreach($errors as $error): ?><p role="alert"><?= ui_escape($error) ?></p><?php endforeach; ?>
<section class="ui-card"><h2><?= $filter==='pending'?'Pending Reviews':'Submission History' ?></h2><?php if(!$items&&!$errors): ?><p>No items <?= $filter==='pending'?'need your review.':'in this view.' ?></p><?php endif; ?><div class="fr-table-wrap" tabindex="0" role="region" aria-label="Submitted items"><table><thead><tr><th scope="col">Type</th><th scope="col">Period</th><th scope="col">Submitted By</th><th scope="col">Submitted Date (UTC)</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><th scope="row"><?= ui_escape($item['type']) ?></th><td><?= ui_escape($item['period']) ?></td><td><?= ui_escape($item['who']??'Not recorded') ?></td><td><?= ui_escape($item['date']) ?></td><td><?= ui_badge($item['state'],in_array($item['state'],['Requested','Submitted'],true)?'pending':'neutral') ?></td><td><a class="ui-button" href="<?= ui_escape($item['url']) ?>">Open<?= ui_icon('chevron') ?></a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php layout_end(); ?>
